CREATE FUNCTION public.student_subject_names() RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT coalesce(jsonb_object_agg(es.id::text,su.name),'{}') FROM public.exam_subjects es JOIN public.teacher_assignments a ON a.id=es.assignment_id JOIN public.subjects su ON su.id=a.subject_id JOIN public.examinations e ON e.id=es.examination_id WHERE public.can_read_sheet(es.id) OR (public.has_role(auth.uid(),'student') AND e.status='PUBLISHED' AND EXISTS(SELECT 1 FROM public.students s WHERE s.profile_id=auth.uid() AND s.section_id=a.section_id AND s.session_id=e.session_id AND s.active)) $$; REVOKE ALL ON FUNCTION public.student_subject_names() FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.student_subject_names() TO authenticated;